// 安全修复方案 1: 使用白名单机制（推荐）
import { spawn } from 'child_process';

// 定义允许执行的安全命令白名单
const ALLOWED_TOOLS = {
  'hostname': 'hostname',
  'uname': ['uname', '-a'],
  'uptime': 'uptime',
  'df': ['df', '-h'],
  'du': ['du', '-sh', '.']
};

export async function getSystemInfo(toolName: string): Promise<string> {
  // 1. 验证工具名称是否在白名单中
  const allowedCommand = ALLOWED_TOOLS[toolName];
  if (!allowedCommand) {
    throw new Error(`Tool '${toolName}' is not allowed`);
  }

  // 2. 使用 spawn 而非 exec，避免 Shell 解析
  // 3. 将命令和参数分开作为数组传递
  const command = Array.isArray(allowedCommand) ? allowedCommand[0] : allowedCommand;
  const args = Array.isArray(allowedCommand) ? allowedCommand.slice(1) : [];

  return new Promise((resolve, reject) => {
    spawn(command, args)
      .stdout.on('data', (data) => resolve(data.toString()))
      .stderr.on('data', (data) => reject(new Error(data.toString())))
      .on('error', reject);
  });
}

// 安全修复方案 2: 输入验证（辅助）
import { spawn } from 'child_process';

// 严格的命令白名单验证
const VALID_COMMANDS = ['ls', 'pwd', 'date', 'whoami'];

function validateCommand(cmd: string): boolean {
  // 只允许字母、数字、连字符、下划线和空格
  const validPattern = /^[a-zA-Z0-9_\-\s]+$/;
  return validPattern.test(cmd) && VALID_COMMANDS.includes(cmd.trim());
}

export async function getSystemInfo(tool: string): Promise<string> {
  // 1. 严格验证输入格式
  if (!validateCommand(tool)) {
    throw new Error('Invalid command');
  }

  // 2. 使用 spawn 避免注入
  const parts = tool.trim().split(/\s+/);
  return new Promise((resolve, reject) => {
    spawn(parts[0], parts.slice(1))
      .stdout.on('data', (data) => resolve(data.toString()))
      .stderr.on('data', (data) => reject(new Error(data.toString())))
      .on('error', reject);
  });
}

// 安全修复方案 3: 使用参数化命令（最佳实践）
import { spawn } from 'child_process';

// 将用户输入限制为预定义的选项
enum SystemTool {
  HOSTNAME = 'hostname',
  UPTIME = 'uptime',
  DATE = 'date'
}

export async function getSystemInfo(tool: SystemTool): Promise<string> {
  return new Promise((resolve, reject) => {
    spawn(tool, [])
      .stdout.on('data', (data) => resolve(data.toString()))
      .stderr.on('data', (data) => reject(new Error(data.toString())))
      .on('error', reject);
  });
}

// 调用示例
await getSystemInfo(SystemTool.HOSTNAME);
